        Get-RequiredOption -Options $options -Name 'data-file'
    }
    else {
        $defaultDataFile
    }
    $asJson = $options.Contains('json')
    $templateFile = Get-TemplateStorePath -DataFile $dataFile
    $templateBanner = Join-Path (Split-Path -Parent $PSScriptRoot) 'assets/template.txt'

